  if x['exam']=='CMI-MSDS':x.update(cmi_rubric_version='cmi-msds-review-rubric-v1',cmi_dimensions={'subject_coverage':2,'skills_required':2,'techniques_required':2,'analysis_level':2,'speed':1,'reasoning_kind':2},cmi_pass_author_review=True,cmi_fit_rationale='Compact pseudocode/state reasoning with an edge-case or interpretation check; timing estimate is unpiloted.')
