def map_svg(d):
 s='<svg class="mindmap" viewBox="0 0 1000 440" role="img" aria-label="Day '+str(d['day'])+' concept map"><title>'+E(d['title'])+' concept map</title><rect x="15" y="175" width="235" height="85" rx="12" fill="#176955"/><text x="132" y="222" text-anchor="middle" fill="white" font-size="23">DSA · Day '+str(d['day'])+'</text>'
 for i,(t,a,b) in enumerate(d['map']):
  y=12+i*106;s+=f'<path d="M250 217 C320 217 330 {y+45} 385 {y+45}" fill="none" stroke="#7d9eae" stroke-width="2"/><rect x="385" y="{y}" width="600" height="92" rx="8" fill="#eef4f7" stroke="#a4bac4"/><text x="405" y="{y+27}" font-size="22" font-weight="600">{E(t)}</text><text x="405" y="{y+54}" font-size="18">{E(a)}</text><text x="405" y="{y+79}" font-size="18">{E(b)}</text>'
 return s+'</svg>'
def shell(title,s):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+E(title)+' · Aleph</title><link rel="stylesheet" href="/psets/material-page.css"><link rel="stylesheet" href="/calculus-review/style.css"><link rel="stylesheet" href="style.css"><script defer src="workspace.js"></script></head><body><main class="wrap">'+s+'</main></body></html>'
for d in D:
 day=d['day'];s=f'<nav><a href="index.html">← Three-week DSA review</a> · <a href="/">Aleph uploads and feedback</a></nav><section class="hero"><p class="eyebrow">Week 1 · Day {day} of 7</p><h1>{E(d["title"])}</h1><p class="sub">{E(d["goal"])}</p><p>Reading anchor: {E(d["source"])}. Use the named topics within those chapters rather than rereading every page. All examples and diagnostic questions here are original.</p></section><section class="panel"><h2>Today’s sequence</h2><p>Review exposition and two examples first (about 30–40 minutes). Then close the exposition and attempt the five-question diagnostic (about 25 minutes plus checking). Record the attempt before opening feedback, then consolidate with the big picture and mind map. The diagnostic tests post-review retrieval, not a pre-teaching baseline. Estimates need piloting; mark anything not reached.</p><p>Use zero-based indices, Python range’s excluded endpoint, and distinct tree keys unless stated otherwise. The code or trace convention in a question takes precedence over an algorithm name.</p></section><section class="panel accent" id="review">{d["story"]}</section><h2>Two worked examples</h2>'
 for title,prompt,answer in d['worked']:s+='<section class="panel"><h3>'+E(title)+'</h3><p>'+E(prompt)+'</p><p>'+E(answer)+'</p></section>'
 s+='<section class="panel" id="diagnostic"><h2>Diagnostic · five questions</h2><p>Q1–Q2 are multi-select: select all correct options and no others. Q3–Q5 need a short trace or explanation. Every question is worth 2 points; short answers use 1 point for a correct result and 1 for the requested justification. No negative marking. This is a learning diagnostic, not a full mock examination.</p><p id="status" role="status">Drafts and recorded attempts stay on this browser only. Export and upload in the Aleph DSA review subject for server submission.</p>'
 for x in d['questions']:
  ident=x['id'];s+=f'<article class="problem" data-question="{ident}" data-skill="{x["skill"]}"><h3>{ident} · {x["minutes"]} minutes</h3><p>{E(x["prompt"])}</p>'
  if x['type']=='multi-select':
   for j,opt in enumerate(x['options']):s+=f'<label class="option"><input type="checkbox" data-option="{ident}" value="{chr(65+j)}"> {E(opt)}</label>'
  s+=f'<label>Your reasoning<textarea data-answer="{ident}" rows="3"></textarea></label><label>Attempt status<select data-attempt="{ident}"><option value="">Choose</option><option>Attempted</option><option>Not attempted</option><option>Not reached</option></select></label><label>Confidence<select data-confidence="{ident}"><option value="">Not recorded</option><option>Low</option><option>Medium</option><option>High</option></select></label><label>Help or prior exposure<input type="text" data-help="{ident}" placeholder="None, hint used, or reference consulted"></label></article>'
 s+='<label class="confirm"><input type="checkbox" id="confirm-attempt"> I have recorded my attempt, including anything not attempted or not reached.</label><button id="record-attempt" type="button">Record this attempt and open feedback</button><p>Recording freezes a browser-local copy of this attempt and opens the worked feedback. It does not submit work to Aleph. Use the subject upload controls for that.</p></section><section class="panel" id="feedback" hidden><h2>Worked feedback and repair</h2><p id="mcq-result"></p><p>Multi-select questions are checked automatically. Grade short-answer reasoning against the keys; uploading enables Aleph’s existing AI feedback workflow. Correct supported work and independent transfer are different evidence.</p>'
 for x in d['questions']:s+='<article><h3>'+x['id']+'</h3><p>'+E(x['answer'])+'</p><p><strong>Diagnostic tag:</strong> '+E(x['skill'])+'. <strong>Likely trap:</strong> '+E(x['trap'])+'. <strong>First step:</strong> '+E(x['first'])+'.</p></article>'
 s+='<h3>Targeted repair</h3><p>'+E(d['repair'])+'</p><h3>A fresh check</h3><p>'+E(d['retest'][0])+'</p><details><summary>Fresh-check answer — open after trying</summary><p>'+E(d['retest'][1])+'</p></details></section>'
 s+='<section class="panel" id="big-picture" hidden><h2>The big picture</h2><p>'+E(d['goal'])+' Explain the result through a representation, an invariant, and a cost model. A correct final array or number is incomplete when the question asks why the steps work.</p>'+map_svg(d)+'<details><summary>Text version of the mind map</summary><ul>'+''.join('<li><strong>'+E(t)+':</strong> '+E(a)+'; '+E(b)+'.</li>' for t,a,b in d['map'])+'</ul></details><label>Correction note: first broken step, next drill, fresh-check result<textarea data-correction="note" rows="4"></textarea></label></section>'
 s+='<section class="panel"><h2>Keep and submit your work</h2><button id="export" type="button">Export responses and attempt record</button> <button type="button" onclick="window.print()">Print current view</button><p>Go to <strong>Aleph → Subjects → DSA: three-week Skiena review</strong> to upload the export or written solutions. The original local attempt is retained separately from later corrections. Completion is not a mastery claim.</p></section><nav>'+(f'<a href="day-{day-1:02}.html">← Previous day</a> · ' if day>1 else '')+(f'<a href="day-{day+1:02}.html">Next day →</a>' if day<7 else '<a href="index.html#week2">Next: Week 2 plan</a>')+'</nav><footer>Book/syllabus sources and the explicit overlap map are on the <a href="index.html#sources">course index</a>. No calendar deadlines assigned.</footer>'
 # Feedback is not present as visible content before the local attempt is recorded.
 keys={x['id']:x['correct'] for x in d['questions'] if x['type']=='multi-select'}
 s+='<script>window.DSA_KEYS='+json.dumps(keys)+';</script>'
 (R/f'day-{day:02}.html').write_text(shell(d['title'],s))
